const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// Color palette: Ocean Gradient / Technical
const COLORS = {
  primary: "065A82",     // deep blue
  secondary: "1C7293",   // teal
  accent: "21295C",      // midnight
  light: "F8FAFC",       // off-white
  muted: "64748B",       // slate gray
  white: "FFFFFF",
  darkText: "1E293B",
  chartDesktop: "065A82",
  chartMobile: "14B8A6",
  chartAccent: "F59E0B",
  chartDecline: "EF4444",
  cardBg: "F1F5F9",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "State of the Web 2020–2025: HTTP Archive Trends in Page Weight, Protocols, and Security";
pres.author = "HTTP Archive Analysis";
pres.subject = "Web Performance & Infrastructure Trends";

// Helper to add a subtle footer bar
function addFooter(slide, text = "Source: HTTP Archive — State of the Web Report (Jan 2020 – Mar 2026)") {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: 10, h: 0.275,
    fill: { color: COLORS.primary },
  });
  slide.addText(text, {
    x: 0.5, y: 5.35, w: 9, h: 0.275,
    fontSize: 9, color: COLORS.white, fontFace: "Calibri",
    valign: "middle", align: "left",
  });
}

// ========================
// SLIDE 1: Title Slide
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.accent };

  // Decorative top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.15,
    fill: { color: COLORS.secondary },
  });

  // Large title
  slide.addText("State of the Web 2020–2025", {
    x: 0.6, y: 1.6, w: 8.8, h: 0.9,
    fontSize: 44, bold: true, color: COLORS.white,
    fontFace: "Calibri", align: "left", valign: "middle",
    margin: 0,
  });

  // Subtitle
  slide.addText("HTTP Archive Trends in Page Weight, Protocols, and Security", {
    x: 0.6, y: 2.5, w: 8.8, h: 0.5,
    fontSize: 22, color: "94A3B8",
    fontFace: "Calibri", align: "left", valign: "middle",
    margin: 0,
  });

  // Metadata block
  slide.addText([
    { text: "Data Source: ", options: { bold: true, color: COLORS.white, breakLine: false } },
    { text: "HTTP Archive — State of the Web Report", options: { color: "CBD5E1", breakLine: true } },
    { text: "Time Range: ", options: { bold: true, color: COLORS.white, breakLine: false } },
    { text: "January 2020 – March 2026", options: { color: "CBD5E1", breakLine: true } },
    { text: "Audience: ", options: { bold: true, color: COLORS.white, breakLine: false } },
    { text: "Web Performance Engineers & Front-End Architects", options: { color: "CBD5E1" } },
  ], {
    x: 0.6, y: 3.4, w: 8.8, h: 1.4,
    fontSize: 14, fontFace: "Calibri",
    align: "left", valign: "top",
    lineSpacing: 22,
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: 10, h: 0.275,
    fill: { color: COLORS.secondary },
  });
}

// ========================
// SLIDE 2: Sample Size Growth
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("Crawl Sample Size Tripled", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 32, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("From ~5M to 16M Desktop URLs Since 2020", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 16, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  // Chart: dual-line time series
  slide.addChart(pres.charts.LINE, [
    {
      name: "Desktop URLs",
      labels: ["Jan 2020", "Mid 2020", "Jan 2021", "Mid 2021", "Jan 2022", "Mid 2022", "Jan 2023", "Mid 2023", "2024–2026"],
      values: [5.0, 5.2, 5.5, 5.8, 6.0, 15.0, 15.5, 16.0, 16.0],
    },
    {
      name: "Mobile URLs",
      labels: ["Jan 2020", "Mid 2020", "Jan 2021", "Mid 2021", "Jan 2022", "Mid 2022", "Jan 2023", "Mid 2023", "2024–2026"],
      values: [3.5, 3.7, 4.0, 4.2, 4.5, 10.0, 11.0, 12.5, 12.5],
    },
  ], {
    x: 0.5, y: 1.35, w: 9, h: 3.5,
    lineSize: 3, lineSmooth: true,
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.muted,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true, legendPos: "b",
    showTitle: false,
    valAxisMaxVal: 18,
    valAxisMinVal: 0,
  });

  // Annotation callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 2.0, w: 3.5, h: 0.9,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.1 },
  });
  slide.addText([
    { text: "Sharp jump mid-2022", options: { bold: true, color: COLORS.darkText, breakLine: true, fontSize: 12 } },
    { text: "Desktop: ~5M → ~15M", options: { color: COLORS.muted, breakLine: true, fontSize: 11 } },
    { text: "Mobile: ~3.5M → ~10M", options: { color: COLORS.muted, fontSize: 11 } },
  ], {
    x: 5.9, y: 2.05, w: 3.3, h: 0.8,
    fontFace: "Calibri", align: "left", valign: "middle",
  });

  addFooter(slide);
}

// ========================
// SLIDE 3: Page Weight Trends
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("Median Page Weight Climbs Steadily", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 32, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("~2,000 KB on Desktop; Mobile Tracks Slightly Below", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 16, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  // Chart: line with IQR bands (approximated via three line series)
  slide.addChart(pres.charts.LINE, [
    {
      name: "Desktop (75th %ile)",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [3200, 3400, 3600, 3800, 3900, 4000, 4100],
    },
    {
      name: "Desktop (median)",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [1600, 1700, 1800, 1900, 1950, 1980, 2000],
    },
    {
      name: "Desktop (25th %ile)",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [800, 850, 900, 950, 980, 1000, 1020],
    },
    {
      name: "Mobile (median)",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [1500, 1600, 1700, 1800, 1850, 1880, 1900],
    },
  ], {
    x: 0.5, y: 1.35, w: 9, h: 3.5,
    lineSize: 2.5, lineSmooth: true,
    chartColors: ["93C5FD", COLORS.chartDesktop, "93C5FD", COLORS.chartMobile],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.muted,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true, legendPos: "b",
    showTitle: false,
  });

  // Stat cards
  const cardY = 4.95;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: cardY, w: 2.8, h: 0.9,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("▲ ~25%", {
    x: 0.6, y: cardY + 0.05, w: 2.6, h: 0.45,
    fontSize: 24, bold: true, color: COLORS.chartDesktop,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("Desktop growth since 2020", {
    x: 0.6, y: cardY + 0.45, w: 2.6, h: 0.35,
    fontSize: 11, color: COLORS.muted,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.6, y: cardY, w: 2.8, h: 0.9,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("▲ ~25%", {
    x: 3.7, y: cardY + 0.05, w: 2.6, h: 0.45,
    fontSize: 24, bold: true, color: COLORS.chartMobile,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("Mobile growth since 2020", {
    x: 3.7, y: cardY + 0.45, w: 2.6, h: 0.35,
    fontSize: 11, color: COLORS.muted,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: cardY, w: 2.8, h: 0.9,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("> 4,000 KB", {
    x: 6.8, y: cardY + 0.05, w: 2.6, h: 0.45,
    fontSize: 24, bold: true, color: COLORS.chartAccent,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("75th-percentile desktop", {
    x: 6.8, y: cardY + 0.45, w: 2.6, h: 0.35,
    fontSize: 11, color: COLORS.muted,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  addFooter(slide);
}

// ========================
// SLIDE 4: Requests and Connections
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("76 Requests per Desktop Page While TCP Connections Drop to 12", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 28, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Multiplexing gains from HTTP/2 and HTTP/3 improve connection efficiency", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  // LEFT: Stat cards for requests
  const leftX = 0.5;
  const cardW = 2.6;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: 1.5, w: cardW, h: 1.2,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("76", {
    x: leftX + 0.1, y: 1.55, w: cardW - 0.2, h: 0.6,
    fontSize: 36, bold: true, color: COLORS.chartDesktop,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("Desktop requests (median)", {
    x: leftX + 0.1, y: 2.15, w: cardW - 0.2, h: 0.35,
    fontSize: 11, color: COLORS.muted,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("▲ 2.7%", {
    x: leftX + 0.1, y: 2.45, w: cardW - 0.2, h: 0.2,
    fontSize: 10, color: COLORS.chartDesktop,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: 2.95, w: cardW, h: 1.2,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("71", {
    x: leftX + 0.1, y: 3.0, w: cardW - 0.2, h: 0.6,
    fontSize: 36, bold: true, color: COLORS.chartMobile,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("Mobile requests (median)", {
    x: leftX + 0.1, y: 3.6, w: cardW - 0.2, h: 0.35,
    fontSize: 11, color: COLORS.muted,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("▲ 2.9%", {
    x: leftX + 0.1, y: 3.9, w: cardW - 0.2, h: 0.2,
    fontSize: 10, color: COLORS.chartMobile,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  // RIGHT: Declining line chart for TCP connections
  slide.addChart(pres.charts.LINE, [
    {
      name: "Desktop TCP Connections",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [15, 14, 13.5, 13, 12.5, 12.2, 12.0],
    },
    {
      name: "Mobile TCP Connections",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [15, 14, 13, 12.5, 11.8, 11.3, 11.0],
    },
  ], {
    x: 3.5, y: 1.5, w: 6, h: 3.2,
    lineSize: 3, lineSmooth: true,
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.muted,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true, legendPos: "b",
    showTitle: true, title: "TCP Connections per Page (Median)",
    titleFontSize: 12, titleColor: COLORS.muted,
    valAxisMaxVal: 16, valAxisMinVal: 10,
  });

  // Efficiency callout below chart
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.5, y: 4.85, w: 6, h: 0.55,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("▼ 14.3% desktop  |  ▼ 26.7% mobile  —  fewer connections despite more requests", {
    x: 3.6, y: 4.9, w: 5.8, h: 0.45,
    fontSize: 12, color: COLORS.darkText,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  addFooter(slide);
}

// ========================
// SLIDE 5: HTTPS Near Universal
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("HTTPS Requests Reach 99%", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 32, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Encryption Is Now the Default on the Modern Web", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 16, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  // LARGE stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.4, w: 4.2, h: 2.6,
    fill: { color: COLORS.primary },
    shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.15 },
  });
  slide.addText("99%+", {
    x: 0.6, y: 1.6, w: 4.0, h: 1.0,
    fontSize: 60, bold: true, color: COLORS.white,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("of requests now use HTTPS", {
    x: 0.6, y: 2.55, w: 4.0, h: 0.35,
    fontSize: 14, color: "CBD5E1",
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });
  slide.addText("Desktop: 99.2%  |  Mobile: 99.1%", {
    x: 0.6, y: 2.95, w: 4.0, h: 0.3,
    fontSize: 12, color: "94A3B8",
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  // Small time-series line showing climb from ~80% to 99%
  slide.addChart(pres.charts.LINE, [
    {
      name: "Desktop HTTPS %",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [80, 88, 93, 96, 98, 99, 99.2],
    },
    {
      name: "Mobile HTTPS %",
      labels: ["2020", "2021", "2022", "2023", "2024", "2025", "2026"],
      values: [80, 87, 92, 95, 97.5, 98.8, 99.1],
    },
  ], {
    x: 5.1, y: 1.4, w: 4.4, h: 2.6,
    lineSize: 3, lineSmooth: true,
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.muted,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true, legendPos: "b",
    showTitle: true, title: "HTTPS Adoption Trajectory",
    titleFontSize: 12, titleColor: COLORS.muted,
    valAxisMaxVal: 100, valAxisMinVal: 75,
  });

  // Bottom insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.25, w: 9, h: 0.7,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("▲ ~19–20 percentage points since early 2020  —  unencrypted HTTP is effectively extinct", {
    x: 0.6, y: 4.3, w: 8.8, h: 0.6,
    fontSize: 13, color: COLORS.darkText,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  addFooter(slide);
}

// ========================
// SLIDE 6: HTTP/2 vs HTTP/3
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 28, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Protocol adoption snapshot: HTTP/3 is the fastest-growing metric", {
    x: 0.5, y: 0.85, w: 9, h: 0.35,
    fontSize: 14, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  // Grouped bar chart for latest snapshot
  slide.addChart(pres.charts.BAR, [
    {
      name: "Desktop",
      labels: ["HTTPS", "HTTP/2", "HTTP/3 Support"],
      values: [99.2, 58.6, 38.7],
    },
    {
      name: "Mobile",
      labels: ["HTTPS", "HTTP/2", "HTTP/3 Support"],
      values: [99.1, 57.6, 40.0],
    },
  ], {
    x: 0.5, y: 1.35, w: 5.5, h: 3.5,
    barDir: "col", barGrouping: "clustered",
    chartColors: [COLORS.chartDesktop, COLORS.chartMobile],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.muted,
    valAxisLabelColor: COLORS.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true, legendPos: "b",
    showTitle: true, title: "Protocol Adoption (Latest)",
    titleFontSize: 12, titleColor: COLORS.muted,
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: COLORS.darkText,
    valAxisMaxVal: 110,
  });

  // Right side: HTTP/3 growth callout + caveat
  const rightX = 6.3;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.35, w: 3.2, h: 1.6,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("HTTP/3 Growth", {
    x: rightX + 0.1, y: 1.4, w: 3.0, h: 0.35,
    fontSize: 14, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("From near-zero to ~40% support in under four years", {
    x: rightX + 0.1, y: 1.75, w: 3.0, h: 0.5,
    fontSize: 12, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "top", margin: 0,
  });
  slide.addText("▲ 38,600% desktop  |  ▲ 5,614% mobile", {
    x: rightX + 0.1, y: 2.3, w: 3.0, h: 0.35,
    fontSize: 11, color: COLORS.chartAccent,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 3.15, w: 3.2, h: 1.7,
    fill: { color: COLORS.white },
    shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
  });
  slide.addText("Measurement Caveat", {
    x: rightX + 0.1, y: 3.2, w: 3.0, h: 0.35,
    fontSize: 14, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("HTTP Archive measures HTTP/3 support, not actual usage. Fresh Chrome instances default to HTTP/2 before discovering HTTP/3 capability via Alt-Svc headers.", {
    x: rightX + 0.1, y: 3.55, w: 3.0, h: 1.1,
    fontSize: 11, color: COLORS.muted,
    fontFace: "Calibri", align: "left", valign: "top", margin: 0,
  });

  addFooter(slide);
}

// ========================
// SLIDE 7: Font-Display Adoption
// ========================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("Font-Display Usage Reaches 42% on Mobile", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 32, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
