    x: 0, y: 0, w: 10, h: 0.15,
    fill: { color: COLORS.secondary },
  });

  slide.addText("Key Takeaways", {
    x: 0.6, y: 0.4, w: 8.8, h: 0.6,
    fontSize: 36, bold: true, color: COLORS.white,
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Bigger Pages, Smarter Protocols, Stronger Security", {
    x: 0.6, y: 0.95, w: 8.8, h: 0.35,
    fontSize: 16, color: "94A3B8",
    fontFace: "Calibri", align: "left", valign: "middle", margin: 0,
  });

  // Takeaway cards (5 items)
  const cards = [
    { title: "Page weight keeps climbing", body: "Median desktop pages now transfer ~2,000 KB, roughly 25% heavier than in 2020, driven by richer media and JavaScript." },
    { title: "HTTPS is the new baseline", body: "At 99%+ of requests, unencrypted HTTP is essentially extinct on the modern web." },
    { title: "HTTP/3 is the fastest-growing protocol metric", body: "From near-zero to ~40% support in under four years, HTTP/3 is rapidly becoming mainstream." },
    { title: "Fewer TCP connections despite more requests", body: "Multiplexing in HTTP/2 and HTTP/3 has cut median connections per page by 15–27%, improving network efficiency." },
    { title: "Font-display still underused", body: "At ~40–42% adoption, there is significant room for improvement in avoiding invisible text during font loading." },
  ];

  const startY = 1.45;
  const cardH = 0.62;
  const gap = 0.1;

  cards.forEach((card, i) => {
    const y = startY + i * (cardH + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: y, w: 8.8, h: cardH,
      fill: { color: "1E293B" },
    });
    // Small accent bar on left
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: y, w: 0.06, h: cardH,
      fill: { color: COLORS.secondary },
    });
    slide.addText([
      { text: card.title, options: { bold: true, color: COLORS.white, breakLine: true, fontSize: 12 } },
      { text: card.body, options: { color: "CBD5E1", fontSize: 10 } },
    ], {
      x: 0.8, y: y + 0.06, w: 8.4, h: cardH - 0.12,
      fontFace: "Calibri", align: "left", valign: "top",
    });
  });

  // CTA bar
  const ctaY = 4.85;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: ctaY, w: 8.8, h: 0.5,
    fill: { color: COLORS.primary },
  });
  slide.addText("Call to Action: Benchmark your own sites against these baselines and prioritize optimization efforts.", {
    x: 0.7, y: ctaY, w: 8.6, h: 0.5,
    fontSize: 12, bold: true, color: COLORS.white,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0,
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: 10, h: 0.275,
    fill: { color: COLORS.secondary },
  });
}

// Write file
const outputDir = "/app/output";
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}
pres.writeFile({ fileName: path.join(outputDir, "final_deck.pptx") })
  .then(() => console.log("Presentation saved to /app/output/final_deck.pptx"))
  .catch((err) => {
    console.error("Error saving presentation:", err);
    process.exit(1);
  });
